/* bloqueo de los desbloqueables: null = libre; si no, el requisito. Lee el progreso de «Medallas» (window.MAT_MED); sin él, bloqueado. Un enlace compartido con uno bloqueado se ve igual. */
function camoLockList(){ return CAMO.filter(c=>c[3]&&camoLock(c[0])).map(c=>(window.MAT_LANG==='en'?c[1][1]:c[1][0])+': '+camoLock(c[0]).replace(/^(Se desbloquea|Unlocks) /,'')); }
function camoReq(id){ const c=CAMO.find(x=>x[0]===id); return c&&c[3]?c[3]:null; }
function camoLock(id){ const q=camoReq(id); if(!q) return null; let s=null; try{ s=window.MAT_MED&&window.MAT_MED.state?window.MAT_MED.state():null; }catch(e){}
  const r=s?s.rank|0:0, n=s?s.medals|0:0; if(q.r!=null&&r>=q.r) return null; if(q.n!=null&&n>=q.n) return null;
  let rn=''; try{ rn=window.MAT_MED.rankName(q.r)[window.MAT_LANG==='en'?1:0]; }catch(e){}
  return q.r!=null?(window.MAT_LANG==='en'?'Unlocks at '+(rn||'rank '+q.r):'Se desbloquea en '+(rn||'empleo '+q.r)):(window.MAT_LANG==='en'?'Unlocks with '+q.n+' medals (you have '+n+')':'Se desbloquea con '+q.n+' medallas (tienes '+n+')'); }
const hex=n=>'#'+n.toString(16).padStart(6,'0');
function sw(c){ if(!c) return 'linear-gradient(135deg,#2a2b2d 50%,#8f7a55 50%)'; if(c.m===1) return hex(c.c[0]); return 'conic-gradient('+c.c.map((x,i)=>hex(x)+' '+(i*25)+'% '+((i+1)*25)+'%').join(',')+')'; }
function mkU(){ return {uMode:{value:0},uC0:{value:new THREE.Color()},uC1:{value:new THREE.Color()},uC2:{value:new THREE.Color()},uC3:{value:new THREE.Color()},uS:{value:9},uT:{value:new THREE.Vector3(.55,.6,.65)},uInv:{value:new THREE.Matrix4()}}; }
function setU(U,id){ const c=(CAMO.find(x=>x[0]===id)||CAMO[0])[2]; if(!c){ U.uMode.value=0; return; } U.uMode.value=c.m; c.c.forEach((x,i)=>U['uC'+i].value.setHex(x)); for(let i=c.c.length;i<4;i++) U['uC'+i].value.setHex(c.c[0]); if(c.s) U.uS.value=c.s; if(c.t) U.uT.value.set(...c.t); }
const GHEAD=`varying vec3 vCP; uniform int uMode; uniform vec3 uC0,uC1,uC2,uC3; uniform float uS; uniform vec3 uT;
float h3(vec3 p){ p=fract(p*0.3183099+0.1); p*=17.0; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float vn(vec3 x){ vec3 i=floor(x), f=fract(x); f=f*f*(3.0-2.0*f);
 return mix(mix(mix(h3(i),h3(i+vec3(1,0,0)),f.x),mix(h3(i+vec3(0,1,0)),h3(i+vec3(1,1,0)),f.x),f.y),mix(mix(h3(i+vec3(0,0,1)),h3(i+vec3(1,0,1)),f.x),mix(h3(i+vec3(0,1,1)),h3(i+vec3(1,1,1)),f.x),f.y),f.z); }
float fbm(vec3 p){ return 0.55*vn(p)+0.3*vn(p*2.03+7.1)+0.15*vn(p*4.1+3.7); }
`;
const GCOL=`
if(uMode==1){ diffuseColor.rgb=uC0; } else if(uMode==3){ vec3 cp=floor(vCP*uS*4.0)/4.0; vec3 cc=uC0; if(fbm(cp)>uT.x) cc=uC1; if(fbm(cp*1.6+vec3(11.3,4.1,8.7))>uT.y) cc=uC2; if(fbm(cp*2.2+vec3(3.1,17.2,5.9))>uT.z) cc=uC3; diffuseColor.rgb=cc; } else if(uMode==2){ vec3 cp=vCP*uS; vec3 cc=uC0; if(fbm(cp)>uT.x) cc=uC1; if(fbm(cp*1.6+vec3(11.3,4.1,8.7))>uT.y) cc=uC2; if(fbm(cp*2.2+vec3(3.1,17.2,5.9))>uT.z) cc=uC3; diffuseColor.rgb=cc; }`;
const FINR="\n/* acabado: micro-grano y desgaste suave (rugosidad y color) para que el pol\u00edmero y el anodizado no se vean de pl\u00e1stico liso */\nfloat fg=vn(vCP*900.0), fm=vn(vCP*45.0+vec3(5.3,1.7,9.1)); roughnessFactor=clamp(roughnessFactor+(fg-0.5)*0.16+(fm-0.5)*0.14,0.05,1.0);";
const FINC='\ndiffuseColor.rgb*=0.95+0.1*vn(vCP*60.0+vec3(2.1,7.7,3.3));';
const FINS='\nfloat fb=vn(vec3(vCP.x*1400.0,vCP.y*1400.0,vCP.z*40.0)); roughnessFactor=clamp(roughnessFactor+(fb-0.5)*0.2,0.05,1.0);';
/* acero: rayado fino a lo largo del arma (rugosidad), sin camuflaje */
function finishPatch(m,U){ m.onBeforeCompile=sh=>{ Object.assign(sh.uniforms,U); sh.vertexShader='varying vec3 vCP;\nuniform mat4 uInv;\n'+sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvCP=(uInv*modelMatrix*vec4(transformed,1.0)).xyz;');
  sh.fragmentShader=GHEAD+sh.fragmentShader.replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>'+FINS); }; m.customProgramCacheKey=()=>'matfin1'; }
const WOODM={'AK-47_2_Material_2':0x6e3b21,'Dragunov_SVD_1_Material_3':0x70391f,'Dragunov_SVD_1_Material_7':0x5a3420,'M1_Garand_1_Material_2':0x5c3b25,'M1911_2_Material_3':0x4d2e1d};
/* Calidad (11 nov 2026): la madera de fábrica (AK-47, SVD, M1 Garand, cachas de la M1911) llevaba color plano y se leía como plástico; ahora veta procedimental en el shader (sin texturas que descargar). El camuflaje la sigue tapando. */
const WOODG=`
if(uMode==0){ vec3 wp=vCP; float wn=fbm(vec3(wp.x*22.0,wp.y*22.0,wp.z*2.2)); float w2=vn(vec3(wp.x*70.0,wp.y*70.0,wp.z*6.0)); float rg=fract((wp.y+wp.x*0.45)*120.0+wn*9.0+w2*1.5);
  float st=smoothstep(0.0,0.45,rg)*smoothstep(1.0,0.55,rg); float fib=vn(vec3(wp.x*1100.0,wp.y*1100.0,wp.z*30.0));
  diffuseColor.rgb*=mix(0.74,1.06,st)*(0.93+0.12*fib)*(0.88+0.24*wn); }`;
function camoPatch(m,U){
  m.onBeforeCompile=sh=>{ Object.assign(sh.uniforms,U);
    sh.vertexShader='varying vec3 vCP;\nuniform mat4 uInv;\n'+sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvCP=(uInv*modelMatrix*vec4(transformed,1.0)).xyz;');
    sh.fragmentShader=GHEAD+sh.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>'+(m.userData.wood?WOODG:'')+GCOL)
      .replace('#include <metalnessmap_fragment>','#include <metalnessmap_fragment>\nif(uMode>0){ metalnessFactor=min(metalnessFactor,0.12); }')
      .replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nif(uMode>0){ roughnessFactor=max(roughnessFactor,0.62); }'+FINR)
      .replace(GCOL,GCOL+FINC); };
  m.customProgramCacheKey=()=>m.userData.wood?'matcamo2w':'matcamo2';
}
/* Materiales PBR: los modelos traen solo color plano; M.A.T asigna metal/rugosidad por tipo de pieza. */
function pbr(c){ if(c.userData.kit) return; const col=c.color, r=col.r,g=col.g,b=col.b, mx=Math.max(r,g,b), mn=Math.min(r,g,b), lum=0.2126*r+0.7152*g+0.0722*b, sat=mx-mn, nm=c.name||'';
  if(/round|bullet|brass|casing/i.test(nm)){ c.metalness=1; c.roughness=0.3; c.userData.nocamo=1; }
  else if(c.transparent||c.opacity<1||/glass|lens/i.test(nm)){ c.userData.nocamo=1; c.roughness=Math.min(c.roughness,0.08); c.metalness=0.1; }
  else if(c.emissiveIntensity>0&&c.emissive&&(c.emissive.r+c.emissive.g+c.emissive.b)>0){ c.userData.nocamo=1; }
  else if(sat<0.05&&lum>0.2){ c.metalness=0.82; c.roughness=0.34; c.userData.nocamo=1; }          // piezas de acero (cerrojo, pasadores)
  else if(sat<0.05&&lum<0.02){ c.metalness=0.35; c.roughness=0.42; col.setRGB(Math.max(r,0.032),Math.max(g,0.032),Math.max(b,0.034)); }   // negro puro -> negro real (albedo ~3 %), para que se lea la forma                             // aluminio anodizado / fosfatado negro
  else if(sat<0.05){ c.metalness=0.15; c.roughness=0.55; col.multiplyScalar(0.62); }              // acabado gris oscuro -> más próximo al negro real
  else { c.metalness=0.05; c.roughness=0.64; const gr=lum; col.setRGB(gr+(r-gr)*0.55,gr+(g-gr)*0.55,gr+(b-gr)*0.55).multiplyScalar(0.82); } // polímero de color (FDE, verde): menos saturado
  c.envMapIntensity=1;
}
function prep(root,U,cache){ root.traverse(o=>{ if(!o.isMesh) return; o.castShadow=true; o.receiveShadow=true;
  const one=m=>{ let k=cache.get(m); if(k) return k; k=m.userData.kit?m:m.clone(); if(!m.userData.kit){ pbr(k); const wd=WOODM[m.name]; if(wd!=null){ k.userData.wood=1; k.color.set(wd); k.metalness=0; k.roughness=0.5; } } if(!k.userData.nocamo&&!/glass|lens|reticle|ret_|dot/i.test(k.name||'')) camoPatch(k,U); else if(k.metalness>0.5&&!k.transparent&&!/glass|lens|reticle|ret_|dot/i.test(k.name||'')&&!m.userData.kit) finishPatch(k,U); cache.set(m,k); return k; };
  o.material=Array.isArray(o.material)?o.material.map(one):one(o.material); }); }

/* HDRI de estudio (Poly Haven, CC0): 256×128 RGBE sin compresión */
let ENVP=null;
function envData(){ if(!ENVP) ENVP=fetch(DIR+'env_studio.rgbe?v='+VER).then(r=>{ if(!r.ok) throw 0; return r.arrayBuffer(); }).then(buf=>{ const u=new Uint8Array(buf), Wd=256, H=128, f=new Uint16Array(Wd*H*4), th=THREE.DataUtils.toHalfFloat, one=th(1);
  for(let y=0;y<H;y++) for(let x=0;x<Wd;x++){ const i=(y*Wd+x)*4, o=((H-1-y)*Wd+x)*4, e=u[i+3], s=e?Math.pow(2,e-136):0; f[o]=th(u[i]*s); f[o+1]=th(u[i+1]*s); f[o+2]=th(u[i+2]*s); f[o+3]=one; }
  return f; }).catch(e=>{ ENVP=null; throw e; }); return ENVP; }

