    if(s==='mag'&&m.top!=null&&on.optic){ const o=ACC[on.optic]; return {p:[0,m.top,(m.oz2!=null?m.oz2:m.oz)-((o.mm||100)/2+(x.mm||100)/2+6)*0.00118]}; }
