export function route(app,ctx,p){
  stop();
  if(!document.getElementById('armcss')){ const s=document.createElement('style'); s.id='armcss'; s.textContent=CSS; document.head.appendChild(s); }
  const id=(p[1]||'').split('?')[0];
  const w=id&&W.find(x=>x.id===id||x.V.some(v=>v.id===id));
  if(id&&!w) return ctx.notfound?ctx.notfound():hub(app,ctx);
  /* carga: el modelo 3D se pide ya, en paralelo con la construcción de la página (antes esperaba a que estuviera montada la interfaz) */
  if(w){ try{ const q=new URLSearchParams((location.hash.split('?')[1]||'')), vi=w.V.findIndex(x=>x.id===q.get('v')), v=w.V[vi>=0?vi:(w.V.find(x=>x.id===id)?w.V.findIndex(x=>x.id===id):0)]; if(v&&v.file) getGLB(v.file).catch(()=>{}); }catch(e){} return page(app,ctx,w); }
  const r=hub(app,ctx);
  /* en el índice: al tocar (o pasar el ratón por) una ficha, el modelo empieza a descargarse antes de cambiar de página */
  try{ const gr=document.getElementById('amxg'), pf=e=>{ const a=e.target&&e.target.closest&&e.target.closest('a.amx-w'); const x=a&&W.find(z=>z.id===a.dataset.id); if(x&&x.V[0]&&x.V[0].file) getGLB(x.V[0].file).catch(()=>{}); };
    if(gr&&!gr.dataset.pf){ gr.dataset.pf=1; gr.addEventListener('pointerdown',pf,{passive:true}); } }catch(e){}
  return r;
}
